import threading
import time

# Tolerance used when comparing token counts. Continuous refill produces
# values like 0.9999999999999999 where 1.0 is meant; without this a client
# polling at an exact refill interval could be denied a token it has earned.
_EPSILON = 1e-9


class Bucket:
    def __init__(self, capacity, rate, now):
        self.capacity = capacity
        self.rate = rate
        self.tokens = float(capacity)
        self.last = now

    def refill(self, now):
        elapsed = now - self.last
        if elapsed <= 0:
            return
        # Keep fractional tokens: truncating here would discard the unused
        # fraction every time a frequent client polls, so their bucket would
        # never make progress.
        self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)
        self.last = now
        # Avoid tiny residues at the boundaries.
        if self.capacity - self.tokens <= _EPSILON:
            self.tokens = float(self.capacity)
        elif self.tokens <= _EPSILON:
            self.tokens = 0.0

    def try_take(self, now, cost=1):
        self.refill(now)
        if self.tokens + _EPSILON >= cost:
            self.tokens -= cost
            if -_EPSILON <= self.tokens <= _EPSILON:
                self.tokens = 0.0
            return True
        return False

    def wait_time(self, now, cost=1):
        """Seconds until `cost` tokens will be available (0 if available now)."""
        if cost > self.capacity:
            return float("inf")
        self.refill(now)
        if self.tokens + _EPSILON >= cost:
            return 0.0
        missing = cost - self.tokens
        return missing / self.rate

